function myPow(x, n) {
  let e = Math.abs(n), base = x, result = 1;
  while (e > 0) {
    if (e % 2 === 1) result *= base;      // this bit of the exponent is 1
    base *= base;                         // x, x^2, x^4, x^8, ...
    e = Math.floor(e / 2);
  }
  return n < 0 ? 1 / result : result;
}

def my_pow(x, n):
    e, base, result = abs(n), x, 1.0
    while e > 0:
